    for (i = 0; i < ctxt->txtNr; i++) {
		if (xmlStrEqual(URL, ctxt->txturlTab[i])) {
		    /* skip reuse: fall through to normal loading path to avoid use-after-free */
		    break;
		}
    }
"""
    s2 = s.replace(old, new)
